"""Regenerate the auto-generated results section of README.md.

Every number displayed in the README comes from this script -- numbers are never
written by hand. Run with:

    python -m scripts.generate_results          # rewrite the README section
    python -m scripts.generate_results --check  # fail if README is out of sync (CI)
"""

from __future__ import annotations

import argparse
import math
import sys
from collections.abc import Callable
from pathlib import Path

import pandas as pd

from data.download import END, START, SYMBOLS
from data.loader import load_ohlcv, read_manifest
from engine.backtest import BacktestConfig, run_backtest
from engine.metrics import summarize
from strategies import buy_and_hold_signal, ma_crossover_signal

README_PATH = Path(__file__).resolve().parent.parent / "README.md"
BEGIN_MARK = "<!-- RESULTS:BEGIN -->"
END_MARK = "<!-- RESULTS:END -->"

CONFIG = BacktestConfig(fee_bps=10.0, slippage_bps=0.0)

STRATEGIES: list[tuple[str, Callable[[pd.DataFrame], pd.Series]]] = [
    ("Buy & hold", buy_and_hold_signal),
    ("MA crossover (20/50)", ma_crossover_signal),
]


def _pct(x: float) -> str:
    return "—" if not math.isfinite(x) else f"{x:+.2%}"


def _pct_unsigned(x: float) -> str:
    return "—" if not math.isfinite(x) else f"{x:.2%}"


def _num(x: float) -> str:
    return "—" if not math.isfinite(x) else f"{x:.2f}"


def build_block() -> str:
    manifest = read_manifest()
    lines = [
        BEGIN_MARK,
        "_Generated by `python -m scripts.generate_results` — do not edit by hand"
        " (CI enforces sync)._",
        "",
        f"**Period:** {START[:10]} → {END[:10]} (1d candles, UTC) · "
        f"**Costs:** {CONFIG.fee_bps:.0f} bps fee + {CONFIG.slippage_bps:.0f} bps slippage"
        " per trade · **Execution:** signal at close[t], fill at open[t+1] · "
        "**Annualization:** √365",
        "",
        "| Symbol | Strategy | Total return | CAGR | Sharpe | Sortino | Max drawdown"
        " | Ann. turnover | Win rate |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for symbol in SYMBOLS:
        prices = load_ohlcv(symbol)  # hash-verified load
        for name, strategy in STRATEGIES:
            m = summarize(run_backtest(prices, strategy(prices), CONFIG))
            lines.append(
                f"| {symbol} | {name} | {_pct(m['total_return'])} | {_pct(m['cagr'])} "
                f"| {_num(m['sharpe'])} | {_num(m['sortino'])} | {_pct(m['max_drawdown'])} "
                f"| {m['annualized_turnover']:.1f} | {_pct_unsigned(m['win_rate'])} |"
            )
    hashes = " · ".join(
        f"{symbol} `{manifest['datasets'][symbol]['sha256'][:12]}…`" for symbol in SYMBOLS
    )
    lines += ["", f"Data integrity (SHA-256): {hashes}", END_MARK]
    return "\n".join(lines)


def splice(readme: str, block: str) -> str:
    begin = readme.index(BEGIN_MARK)
    end = readme.index(END_MARK) + len(END_MARK)
    return readme[:begin] + block + readme[end:]


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check", action="store_true", help="exit 1 if README is out of sync with the data"
    )
    args = parser.parse_args()

    readme = README_PATH.read_text()
    if BEGIN_MARK not in readme or END_MARK not in readme:
        print(f"ERROR: result markers not found in {README_PATH}", file=sys.stderr)
        return 1

    updated = splice(readme, build_block())
    if args.check:
        if updated != readme:
            print(
                "ERROR: README results are out of sync with the committed data.\n"
                "Run `python -m scripts.generate_results` and commit the diff.",
                file=sys.stderr,
            )
            return 1
        print("README results are in sync.")
        return 0

    README_PATH.write_text(updated)
    print(f"README results section regenerated in {README_PATH}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
